package com.wheelwright.evidence.v2;

import com.fasterxml.jackson.databind.node.*;
import com.wheelwright.evidence.db.SqliteEvidenceStore;
import com.wheelwright.evidence.v2.portfolio.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;

/** Newly constructed R2 falsifiers. Sanitized native shape; temporary store and mocked broker only. */
class PortfolioCurrentExposureTest {
 @TempDir Path directory; SqliteEvidenceStore db; PortfolioRepository repo; AccountDirectory accounts; String account; ObjectNode raw; PortfolioSources sources;
 @BeforeEach void setup()throws Exception{db=new SqliteEvidenceStore(directory.resolve("current.db").toString());repo=new PortfolioRepository(db,JSON);accounts=new AccountDirectory(db,"");account=accounts.bind("test","TASTYTRADE","TEST1234");raw=(ObjectNode)JSON.readTree(Files.readString(Path.of("src/test/resources/tastytrade/xle-api.json")).replace("TTTEST01","TEST1234"));sources=new PortfolioSources(repo,JSON,accounts);observe(raw);}
 @AfterEach void close()throws Exception{db.close();}
 void observe(ObjectNode value)throws Exception{var client=mock(TastytradeClient.class);when(client.holdings("TEST1234")).thenReturn(JSON.writeValueAsBytes(value));when(client.settledCashBalance("TEST1234")).thenThrow(new IllegalStateException("No cash evidence in specimen"));var outcome=new PositionAcquisition(db,accounts,new PositionReadService(db,JSON),client).acquire(account,UUID.randomUUID().toString());assertThat(outcome.status()).as(outcome.result()).isEqualTo("ACCEPTED");sources.refresh(Set.of(account));}
 Document first()throws Exception{String symbol=raw.at("/data/items/0/symbol").asText();return repo.list(Kind.POSITION,Set.of(account)).stream().filter(p->p.value().path("sourceIdentifiers").toString().contains(symbol)).findFirst().orElseThrow();}
 Document construction(Document p)throws Exception{return repo.get(p.value().at("/currentConstruction/href").asText()).orElseThrow();}
 @Test void quantityChangeRenewsCurrentExposureWithoutProvingOccurrence()throws Exception{var before=first();var old=construction(before);var quantity=number(raw.at("/data/items/0/quantity")).add(java.math.BigDecimal.ONE);((ObjectNode)raw.at("/data/items/0")).put("quantity",decimal(quantity));observe(raw);var after=repo.get(before.uri()).orElseThrow();assertThat(number(leaves(construction(after).value().path("composition")).getFirst().path("quantity"))).isEqualByComparingTo(quantity);assertThat(after.value().path("state").asText()).isEqualTo("UNRESOLVED");assertThat(after.value().at("/evaluation/timeline/openedAt").isNull()).isTrue();assertThat(repo.get(old.uri()).orElseThrow().value()).isEqualTo(old.value());}
 @Test void disappearanceFromCompleteSecuritiesSnapshotClearsCurrentExposureWithoutClaimingClosure()throws Exception{var before=first();var old=construction(before);((ArrayNode)raw.at("/data/items")).remove(0);if(raw.path("pagination").isObject())((ObjectNode)raw.path("pagination")).put("total-items",raw.at("/data/items").size());observe(raw);var after=repo.get(before.uri()).orElseThrow();assertThat(leaves(construction(after).value().path("composition"))).isEmpty();assertThat(after.value().path("state").asText()).isEqualTo("UNRESOLVED");assertThat(repo.get(old.uri()).orElseThrow().value()).isEqualTo(old.value());}
 @Test void observedZeroIsNotTerminalClosureAndLaterObservationDoesNotInventOpening()throws Exception{var p=first();((ObjectNode)raw.at("/data/items/0")).put("quantity",0);observe(raw);var zero=repo.get(p.uri()).orElseThrow();assertThat(zero.value().at("/exposure/status").asText()).isEqualTo("ZERO_OBSERVED");assertThat(leaves(construction(zero).value().path("composition"))).isEmpty();assertThat(zero.value().path("state").asText()).isEqualTo("UNRESOLVED");((ObjectNode)raw.at("/data/items/0")).put("quantity",1);observe(raw);var restored=repo.get(p.uri()).orElseThrow();assertThat(leaves(construction(restored).value().path("composition"))).hasSize(1);assertThat(restored.value().at("/evaluation/timeline/openedAt").isNull()).isTrue();}
 @Test void rejectedPartialAndFailedAcquisitionsPreserveLastSuccessfulCut()throws Exception{var p=first();String old=construction(p).uri();String snapshot=new PortfolioSnapshots(repo).current(account).orElseThrow().snapshotId();var incomplete=raw.deepCopy();incomplete.set("pagination",obj().put("page-offset",0).put("total-pages",2));for(boolean failure:List.of(false,true)){var client=mock(TastytradeClient.class);if(failure)when(client.holdings("TEST1234")).thenThrow(new IllegalStateException("Synthetic source failure"));else when(client.holdings("TEST1234")).thenReturn(JSON.writeValueAsBytes(incomplete));assertThat(new PositionAcquisition(db,accounts,new PositionReadService(db,JSON),client).acquire(account,UUID.randomUUID().toString()).status()).isNotEqualTo("ACCEPTED");sources.refresh(Set.of(account));assertThat(new PortfolioSnapshots(repo).current(account).orElseThrow().snapshotId()).isEqualTo(snapshot);assertThat(construction(repo.get(p.uri()).orElseThrow()).uri()).isEqualTo(old);}}
 @Test void incompleteFidelityScopeRetainsPriorFactsButCannotPriceCurrentQuantityAndCashRowsDoNotInvalidateCompleteSecurities()throws Exception{
  String fidelity=accounts.bind("fidelity","FIDELITY","A1");var artifacts=new BrokerageArtifacts(db.getConnection().getMetaData().getURL(),JSON,new PositionReadService(db,JSON));String cash="A1,Portfolio,Cash,SPAXX**,Cash,,4000,,Cash\n";
  String full=PositionsTest.csv("A1,Portfolio,Stocks,SPY,Share inventory,100,50000,--,Cash\n"+cash,"Oct-05-2026");assertThat(artifacts.ingest(fidelity,"full.csv","POSITIONS",full.getBytes(StandardCharsets.UTF_8),UUID.randomUUID().toString()).status()).isEqualTo("ACCEPTED");sources.refresh(Set.of(fidelity));var original=repo.list(Kind.POSITION,Set.of(fidelity)).getFirst();var originalConstruction=construction(original);
  String partial=PositionsTest.csv("A1,Portfolio,Stocks,SPY,Unquantified source,,--,--,Cash\n"+cash,"Oct-06-2026");assertThat(artifacts.ingest(fidelity,"partial.csv","POSITIONS",partial.getBytes(StandardCharsets.UTF_8),UUID.randomUUID().toString()).status()).isEqualTo("ACCEPTED");sources.refresh(Set.of(fidelity));var retained=repo.get(original.uri()).orElseThrow();assertThat(retained.value().at("/exposure/status").asText()).isEqualTo("RETAINED");var view=new PortfolioReadService(repo,sources).read(retained,new BearerAuthenticator.Principal("reader",Set.of("account.positions.read:"+fidelity)),java.time.Instant.now());assertThat(view.at("/evaluation/marketValue/value").isNull()).isTrue();assertThat(view.at("/evaluation/payoff/geometry").isNull()).isTrue();assertThat(repo.get(originalConstruction.uri()).orElseThrow().value()).isEqualTo(originalConstruction.value());
  assertThat(artifacts.ingest(fidelity,"empty-securities.csv","POSITIONS",PositionsTest.csv(cash,"Oct-07-2026").getBytes(StandardCharsets.UTF_8),UUID.randomUUID().toString()).status()).isEqualTo("ACCEPTED");sources.refresh(Set.of(fidelity));var absent=repo.get(original.uri()).orElseThrow();assertThat(absent.value().at("/exposure/status").asText()).isEqualTo("ZERO_OBSERVED");assertThat(absent.value().path("state").asText()).isEqualTo("UNRESOLVED");assertThat(leaves(construction(absent).value().path("composition"))).isEmpty();
 }

}
